def airbnb_search(location, placeId=None, checkin=None, checkout=None, adults=None, children=None, infants=None, pets=None, minPrice=None, maxPrice=None, cursor=None, ignoreRobotsText=None, **_extra):
    import json, os, datetime, base64, hashlib, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0334000" if __import__("os").path.isdir("./environment_mix/0334000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Observability / quota/rate (best-effort; schema may not provide a log collection) ---
    def _log(status, message=None, **extra):
        # If a request log file exists, append. Otherwise no-op.
        for fname in ("request_logs.json", "airbnb_request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + hashlib.sha256(f"airbnb_search|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:20],
                    "endpoint": "airbnb_search",
                    "status": status,
                    "message": message,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now,
                    **extra
                })
                _save(fname, logs)
                break

    # --- Validate inputs ---
    if not isinstance(location, str) or not location.strip():
        _log("error", "Validation error: location")
        return _err("VALIDATION_ERROR", "location must be a non-empty string")

    if placeId is not None and (not isinstance(placeId, str) or not placeId.strip()):
        _log("error", "Validation error: placeId")
        return _err("VALIDATION_ERROR", "placeId must be a non-empty string when provided")

    def _is_date(s):
        return isinstance(s, str) and re.match(r"^\d{4}-\d{2}-\d{2}$", s) is not None

    if checkin is not None and not _is_date(checkin):
        _log("error", "Validation error: checkin")
        return _err("VALIDATION_ERROR", "checkin must be YYYY-MM-DD when provided")
    if checkout is not None and not _is_date(checkout):
        _log("error", "Validation error: checkout")
        return _err("VALIDATION_ERROR", "checkout must be YYYY-MM-DD when provided")

    if checkin is not None and checkout is not None and not (checkin < checkout):
        # Must be rejected (failed) with error_code=INVALID_INPUT while recording attempted query.
        # We'll create/update the query row to failed below.
        invalid_date_range = True
    else:
        invalid_date_range = False

    def _to_int_nonneg(name, v):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number/integer")
        if isinstance(v, float) and not v.is_integer():
            return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        if not isinstance(v, (int, float)):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number/integer")
        iv = int(v)
        if iv < 0:
            return None, _err("VALIDATION_ERROR", f"{name} must be >= 0")
        return iv, None

    adults_i, e = _to_int_nonneg("adults", adults)
    if e: _log("error", "Validation error: adults"); return e
    children_i, e = _to_int_nonneg("children", children)
    if e: _log("error", "Validation error: children"); return e
    infants_i, e = _to_int_nonneg("infants", infants)
    if e: _log("error", "Validation error: infants"); return e
    pets_i, e = _to_int_nonneg("pets", pets)
    if e: _log("error", "Validation error: pets"); return e

    def _to_num_nonneg(name, v):
        if v is None:
            return None, None
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number")
        fv = float(v)
        if fv < 0:
            return None, _err("VALIDATION_ERROR", f"{name} must be >= 0")
        return fv, None

    min_p, e = _to_num_nonneg("minPrice", minPrice)
    if e: _log("error", "Validation error: minPrice"); return e
    max_p, e = _to_num_nonneg("maxPrice", maxPrice)
    if e: _log("error", "Validation error: maxPrice"); return e
    if min_p is not None and max_p is not None and min_p > max_p:
        _log("error", "Validation error: minPrice/maxPrice")
        return _err("VALIDATION_ERROR", "minPrice must be <= maxPrice when both are provided")

    if ignoreRobotsText is None:
        ignoreRobotsText = False
    if not isinstance(ignoreRobotsText, bool):
        _log("error", "Validation error: ignoreRobotsText")
        return _err("VALIDATION_ERROR", "ignoreRobotsText must be a boolean")

    # Cursor must be base64 when present; invalid cursor -> status=failed error_code=INVALID_INPUT
    invalid_cursor = False
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            invalid_cursor = True
        else:
            try:
                # validate=True enforces alphabet/padding
                base64.b64decode(cursor.encode("utf-8"), validate=True)
            except Exception:
                invalid_cursor = True

    # Determine effective location spec for fingerprint (placeId overrides)
    effective_loc = placeId.strip() if isinstance(placeId, str) and placeId.strip() else location.strip()

    fp_payload = {
        "effective_location": effective_loc,
        "placeId": placeId.strip() if isinstance(placeId, str) and placeId.strip() else None,
        "location": location.strip(),
        "checkin": checkin,
        "checkout": checkout,
        "adults": adults_i,
        "children": children_i,
        "infants": infants_i,
        "pets": pets_i,
        "min_price": min_p,
        "max_price": max_p,
        "cursor": cursor
    }
    request_fingerprint = hashlib.sha256(json.dumps(fp_payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()

    # --- Load datastore ---
    queries = _load("airbnb_search_queries.json")
    listings = _load("airbnb_listings.json")
    results = _load("airbnb_search_results.json")

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:20]

    # Find existing query by request_fingerprint (unique constraint)
    q = None
    for row in queries:
        if row.get("request_fingerprint") == request_fingerprint:
            q = row
            break

    # TTL caching (best-effort): if succeeded and completed_at within TTL seconds
    TTL_SECONDS = 15 * 60
    def _parse_dt(s):
        if not s or not isinstance(s, str):
            return None
        try:
            # handle Z
            if s.endswith("Z"):
                s2 = s[:-1]
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2)
        except Exception:
            return None

    fresh_cache = False
    if q and q.get("status") == "succeeded":
        ca = _parse_dt(q.get("completed_at"))
        if ca:
            age = (datetime.datetime.utcnow() - ca).total_seconds()
            if age >= 0 and age <= TTL_SECONDS:
                fresh_cache = True

    # Policy for ignoreRobotsText (internal flag)
    policy_allowed = os.environ.get("AIRBNB_ALLOW_IGNORE_ROBOTS_TEXT", "").lower() in ("1", "true", "yes", "on")

    # Create or update query row; also mark as failed on invalid input while recording attempt
    created = False
    if not q:
        q = {
            "id": _new_id("asq"),
            "location": location.strip(),
            "place_id": placeId.strip() if isinstance(placeId, str) and placeId.strip() else None,
            "checkin": checkin,
            "checkout": checkout,
            "adults": adults_i,
            "children": children_i,
            "infants": infants_i,
            "pets": pets_i,
            "min_price": min_p,
            "max_price": max_p,
            "cursor": cursor,
            "ignore_robots_text": bool(ignoreRobotsText),
            "request_fingerprint": request_fingerprint,
            "executed_at": None,
            "completed_at": None,
            "error_code": None,
            "error_message": None,
            "status": "queued",
            "created_at": _now,
            "updated_at": _now
        }
        queries.append(q)
        created = True
    else:
        # Update stored parameters to latest call (but keep fingerprint-keyed row)
        q["location"] = location.strip()
        q["place_id"] = placeId.strip() if isinstance(placeId, str) and placeId.strip() else None
        q["checkin"] = checkin
        q["checkout"] = checkout
        q["adults"] = adults_i
        q["children"] = children_i
        q["infants"] = infants_i
        q["pets"] = pets_i
        q["min_price"] = min_p
        q["max_price"] = max_p
        q["cursor"] = cursor
        q["ignore_robots_text"] = bool(ignoreRobotsText)
        q["updated_at"] = _now

    # Handle invalid cursor / invalid date range / policy denied as failed attempt
    if invalid_cursor or invalid_date_range or (ignoreRobotsText and not policy_allowed):
        # Transition queued/running -> failed is allowed only from running; but we can set directly since this is "execution result".
        # We still respect lifecycle: queued can go to running/cancelled; so mark running then failed.
        if q.get("status") == "queued":
            q["status"] = "running"
        if q.get("status") == "running":
            q["status"] = "failed"
        else:
            # if already terminal, keep it but still update error fields for this attempt
            q["status"] = "failed" if q.get("status") in ("queued", "running") else q.get("status")
        q["executed_at"] = q.get("executed_at") or _now
        q["completed_at"] = _now
        if ignoreRobotsText and not policy_allowed:
            q["error_code"] = "POLICY_DENIED"
            q["error_message"] = "ignoreRobotsText is not permitted by internal policy"
        else:
            q["error_code"] = "INVALID_INPUT"
            if invalid_cursor:
                q["error_message"] = "Invalid cursor: must be a base64-encoded string"
            else:
                q["error_message"] = "Invalid date range: checkin must be before checkout"
        q["updated_at"] = _now
        _save("airbnb_search_queries.json", queries)
        _log("ok", "Recorded failed search attempt", search_query_id=q["id"], error_code=q["error_code"])
        return {
            "searchQuery": q,
            "results": [],
            "cursor": None,
            "meta": {"cached": False, "total": 0, "has_more": False}
        }

    # If cache is fresh, return cached results ordered by rank without re-fetching
    if fresh_cache:
        qid = q["id"]
        page = [r for r in results if r.get("search_query_id") == qid]
        page.sort(key=lambda r: (r.get("rank", 10**9), r.get("id", "")))
        # join listing data for response convenience
        listing_by_id = {l.get("id"): l for l in listings if l.get("id")}
        out = []
        for r in page:
            l = listing_by_id.get(r.get("listing_id"))
            out.append({"search_result": r, "listing": l})
        _save("airbnb_search_queries.json", queries)  # updated_at already set
        _log("ok", "Returned cached search results", search_query_id=q["id"], cached=True)
        return {
            "searchQuery": q,
            "results": out,
            "cursor": q.get("cursor"),
            "meta": {"cached": True, "total": len(out), "has_more": bool(q.get("cursor"))}
        }

    # Execute "upstream" fetch (offline): mark running then succeed with no new data
    # Lifecycle transitions
    if q.get("status") == "queued":
        q["status"] = "running"
    elif q.get("status") == "running":
        pass
    elif q.get("status") in ("succeeded", "failed", "cancelled"):
        # allow re-run by creating a new query would violate unique fingerprint; so we keep row and just run again
        q["status"] = "running"
    q["executed_at"] = _now
    q["updated_at"] = _now

    # Offline mode: no real upstream; succeed with existing persisted results (if any), otherwise empty.
    qid = q["id"]
    page = [r for r in results if r.get("search_query_id") == qid]
    page.sort(key=lambda r: (r.get("rank", 10**9), r.get("id", "")))

    q["status"] = "succeeded"
    q["completed_at"] = _now
    q["error_code"] = None
    q["error_message"] = None
    q["updated_at"] = _now

    _save("airbnb_search_queries.json", queries)

    listing_by_id = {l.get("id"): l for l in listings if l.get("id")}
    out = []
    for r in page:
        l = listing_by_id.get(r.get("listing_id"))
        out.append({"search_result": r, "listing": l})

    _log("ok", "Search executed (offline/no-upstream)", search_query_id=q["id"], cached=False)
    return {
        "searchQuery": q,
        "results": out,
        "cursor": q.get("cursor"),
        "meta": {"cached": False, "total": len(out), "has_more": bool(q.get("cursor"))}
    }

def airbnb_listing_details(id, checkin=None, checkout=None, adults=None, children=None, infants=None, pets=None, ignoreRobotsText=None, **_extra):
    import json, os, datetime, hashlib, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0334000" if __import__("os").path.isdir("./environment_mix/0334000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, message=None, **extra):
        for fname in ("request_logs.json", "airbnb_request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + hashlib.sha256(f"airbnb_listing_details|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:20],
                    "endpoint": "airbnb_listing_details",
                    "status": status,
                    "message": message,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now,
                    **extra
                })
                _save(fname, logs)
                break

    if not isinstance(id, str) or not id.strip():
        _log("error", "Validation error: id")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    def _is_date(s):
        return isinstance(s, str) and re.match(r"^\d{4}-\d{2}-\d{2}$", s) is not None

    if checkin is not None and not _is_date(checkin):
        _log("error", "Validation error: checkin")
        return _err("VALIDATION_ERROR", "checkin must be YYYY-MM-DD when provided")
    if checkout is not None and not _is_date(checkout):
        _log("error", "Validation error: checkout")
        return _err("VALIDATION_ERROR", "checkout must be YYYY-MM-DD when provided")

    invalid_date_range = False
    if checkin is not None and checkout is not None and not (checkin < checkout):
        invalid_date_range = True

    def _to_int_nonneg(name, v):
        if v is None:
            return None, None
        if isinstance(v, bool):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number/integer")
        if isinstance(v, float) and not v.is_integer():
            return None, _err("VALIDATION_ERROR", f"{name} must be an integer")
        if not isinstance(v, (int, float)):
            return None, _err("VALIDATION_ERROR", f"{name} must be a number/integer")
        iv = int(v)
        if iv < 0:
            return None, _err("VALIDATION_ERROR", f"{name} must be >= 0")
        return iv, None

    adults_i, e = _to_int_nonneg("adults", adults)
    if e: _log("error", "Validation error: adults"); return e
    children_i, e = _to_int_nonneg("children", children)
    if e: _log("error", "Validation error: children"); return e
    infants_i, e = _to_int_nonneg("infants", infants)
    if e: _log("error", "Validation error: infants"); return e
    pets_i, e = _to_int_nonneg("pets", pets)
    if e: _log("error", "Validation error: pets"); return e

    if ignoreRobotsText is None:
        ignoreRobotsText = False
    if not isinstance(ignoreRobotsText, bool):
        _log("error", "Validation error: ignoreRobotsText")
        return _err("VALIDATION_ERROR", "ignoreRobotsText must be a boolean")

    policy_allowed = os.environ.get("AIRBNB_ALLOW_IGNORE_ROBOTS_TEXT", "").lower() in ("1", "true", "yes", "on")

    listings = _load("airbnb_listings.json")
    snaps = _load("airbnb_listing_detail_snapshots.json")

    def _new_id(prefix):
        return prefix + "_" + hashlib.sha256(f"{prefix}|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:20]

    airbnb_listing_id = id.strip()

    # Upsert listing by airbnb_listing_id
    listing = None
    for l in listings:
        if l.get("airbnb_listing_id") == airbnb_listing_id:
            listing = l
            break

    if listing is None:
        listing = {
            "id": _new_id("lst"),
            "airbnb_listing_id": airbnb_listing_id,
            "canonical_url": f"https://www.airbnb.com/rooms/{airbnb_listing_id}",
            "title": None,
            "status": "unknown",
            "last_seen_at": None,
            "created_at": _now,
            "updated_at": _now
        }
        listings.append(listing)
    else:
        if not listing.get("canonical_url"):
            listing["canonical_url"] = f"https://www.airbnb.com/rooms/{airbnb_listing_id}"
        listing["updated_at"] = _now

    # If same context, return most recently stored snapshot; else create a new snapshot version per fetch attempt.
    def _ctx_key(s):
        return (
            s.get("checkin"), s.get("checkout"),
            s.get("adults"), s.get("children"), s.get("infants"), s.get("pets"),
            bool(s.get("ignore_robots_text"))
        )

    desired_ctx = (checkin, checkout, adults_i, children_i, infants_i, pets_i, bool(ignoreRobotsText))
    existing = [s for s in snaps if s.get("listing_id") == listing["id"] and _ctx_key(s) == desired_ctx]
    def _parse_dt(s):
        if not s or not isinstance(s, str): return None
        try:
            return datetime.datetime.fromisoformat(s[:-1] if s.endswith("Z") else s)
        except Exception:
            return None
    if existing:
        existing.sort(key=lambda s: (_parse_dt(s.get("fetched_at")) or datetime.datetime.min), reverse=True)
        latest = existing[0]
        _save("airbnb_listings.json", listings)
        _log("ok", "Returned existing snapshot", listing_id=listing["id"], snapshot_id=latest["id"], cached=True)
        return {"listing": listing, "snapshot": latest, "canonicalUrl": listing.get("canonical_url")}

    # Create new snapshot attempt
    fetched_at = _now
    source_url = listing.get("canonical_url") or f"https://www.airbnb.com/rooms/{airbnb_listing_id}"

    snap = {
        "id": _new_id("snap"),
        "listing_id": listing["id"],
        "checkin": checkin,
        "checkout": checkout,
        "adults": adults_i,
        "children": children_i,
        "infants": infants_i,
        "pets": pets_i,
        "ignore_robots_text": bool(ignoreRobotsText),
        "source_url": source_url,
        "raw_details": {},
        "fetched_at": fetched_at,
        "status": "failed",
        "error_code": None,
        "error_message": None,
        "created_at": _now,
        "updated_at": _now
    }

    # Validate & policy enforcement with recorded snapshot
    if invalid_date_range:
        snap["status"] = "failed"
        snap["error_code"] = "INVALID_INPUT"
        snap["error_message"] = "Invalid date range: checkin must be before checkout"
        snaps.append(snap)
        _save("airbnb_listings.json", listings)
        _save("airbnb_listing_detail_snapshots.json", snaps)
        _log("ok", "Recorded failed snapshot attempt (invalid input)", listing_id=listing["id"], snapshot_id=snap["id"])
        return {"listing": listing, "snapshot": snap, "canonicalUrl": listing.get("canonical_url")}

    if ignoreRobotsText and not policy_allowed:
        snap["status"] = "failed"
        snap["error_code"] = "POLICY_DENIED"
        snap["error_message"] = "ignoreRobotsText is not permitted by internal policy"
        snaps.append(snap)
        _save("airbnb_listings.json", listings)
        _save("airbnb_listing_detail_snapshots.json", snaps)
        _log("ok", "Recorded failed snapshot attempt (policy denied)", listing_id=listing["id"], snapshot_id=snap["id"])
        return {"listing": listing, "snapshot": snap, "canonicalUrl": listing.get("canonical_url")}

    # Offline "fetch": succeed with minimal structured payload
    snap["raw_details"] = {
        "airbnb_listing_id": airbnb_listing_id,
        "canonical_url": listing.get("canonical_url"),
        "context": {
            "checkin": checkin, "checkout": checkout,
            "adults": adults_i, "children": children_i, "infants": infants_i, "pets": pets_i
        },
        "fetched_offline": True
    }
    snap["status"] = "succeeded"
    snap["updated_at"] = _now
    snap["error_code"] = None
    snap["error_message"] = None

    # Update listing last_seen/status transition to active on success
    listing["last_seen_at"] = fetched_at
    # lifecycle: unknown -> active, inactive -> active allowed; deleted cannot transition
    if listing.get("status") in ("unknown", "inactive"):
        listing["status"] = "active"
    listing["updated_at"] = _now

    snaps.append(snap)
    _save("airbnb_listings.json", listings)
    _save("airbnb_listing_detail_snapshots.json", snaps)

    _log("ok", "Snapshot fetched (offline/no-upstream)", listing_id=listing["id"], snapshot_id=snap["id"], cached=False)
    return {"listing": listing, "snapshot": snap, "canonicalUrl": listing.get("canonical_url")}

def airbnb_search_queries_list(status=None, location=None, placeId=None, requestFingerprint=None, executedAfter=None, executedBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, hashlib, base64, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0334000" if __import__("os").path.isdir("./environment_mix/0334000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    _t0 = time.time()
    _now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, message=None, **extra):
        for fname in ("request_logs.json", "airbnb_request_logs.json", "usage_logs.json", "audit_logs.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                logs.append({
                    "id": "req_" + hashlib.sha256(f"airbnb_search_queries_list|{_now}|{time.time()}".encode("utf-8")).hexdigest()[:20],
                    "endpoint": "airbnb_search_queries_list",
                    "status": status_s,
                    "message": message,
                    "latency_ms": int((time.time() - _t0) * 1000),
                    "timestamp": _now,
                    **extra
                })
                _save(fname, logs)
                break

    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log("error", "Validation error: status")
            return _err("VALIDATION_ERROR", "status must be one of queued,running,succeeded,failed,cancelled")

    if location is not None and (not isinstance(location, str)):
        _log("error", "Validation error: location")
        return _err("VALIDATION_ERROR", "location must be a string")
