    ea, e = _parse_iso(executedAfter, "executedAfter")
    if e: _log("error", "Validation error: executedAfter"); return e
    eb, e = _parse_iso(executedBefore, "executedBefore")
    if e: _log("error", "Validation error: executedBefore"); return e

    if limit is None:
