    if err:
        e = _err("VALIDATION_ERROR", err)
        _log("error", e["error"], meta={"listingId": listingId})
        return e
    p, err = _coerce_nonneg_intish(pets, "pets")
    if err:
        e = _err("VALIDATION_ERROR", err)
        _log("error", e["error"], meta={"listingId": listingId})
        return e

    lim, lerr = _parse_limit(limit)
    if lerr:
        e = _err("VALIDATION_ERROR", lerr)
        _log("error", e["error"], meta={"listingId": listingId})
        return e

    offset, cerr = _decode_cursor(cursor)
    if cerr:
        e = _err("VALIDATION_ERROR", cerr)
        _log("error", e["error"], meta={"listingId": listingId})
        return e

    listings = _load("airbnb_listings.json")
    if not isinstance(listings, list):
        listings = []
    snapshots = _load("airbnb_listing_detail_snapshots.json")
    if not isinstance(snapshots, list):
        snapshots = []

    # Resolve listing context:
    # listingId is documented as airbnb_listings.id; however callers may mistakenly pass a search_query_id.
    listing_row = None
    if any(isinstance(r, dict) and r.get("id") == listingId for r in listings):
        for r in listings:
            if isinstance(r, dict) and r.get("id") == listingId:
                listing_row = r
                break
    else:
        # Relaxation to accept mis-specified IDs observed in audit:
        # If listingId matches an existing search_query_id, pick the most recent snapshot for any listing
        # referenced by that query, and list snapshots for that listing.
        sqs = _load("airbnb_search_queries.json")
        if not isinstance(sqs, list):
            sqs = []
        squery_exists = any(isinstance(r, dict) and r.get("id") == listingId for r in sqs)
        if squery_exists:
            sresults = _load("airbnb_search_results.json")
            if not isinstance(sresults, list):
                sresults = []
            candidate_listing_ids = []
            for sr in sresults:
                if isinstance(sr, dict) and sr.get("search_query_id") == listingId:
                    lid = sr.get("listing_id")
                    if isinstance(lid, str):
                        candidate_listing_ids.append(lid)
            # Choose the listing with newest fetched_at snapshot (or any if none)
            newest = None
            chosen_lid = None
            for lid in set(candidate_listing_ids):
                for snap in snapshots:
                    if isinstance(snap, dict) and snap.get("listing_id") == lid:
                        fa = snap.get("fetched_at")
                        if isinstance(fa, str):
                            if newest is None or fa > newest:
                                newest = fa
                                chosen_lid = lid
            if chosen_lid is None and candidate_listing_ids:
                chosen_lid = candidate_listing_ids[0]
            if chosen_lid is not None:
                for r in listings:
                    if isinstance(r, dict) and r.get("id") == chosen_lid:
                        listing_row = r
                        listingId = chosen_lid  # normalize to real listing id for filtering
                        break

    if listing_row is None:
        e = _err("NOT_FOUND", "unknown listingId")
        _log("error", e["error"], meta={"listingId": listingId})
        return e

    # Filter snapshots
    def _match(s):
        if not isinstance(s, dict):
            return False
        if s.get("listing_id") != listingId:
            return False
        if status is not None and s.get("status") != status:
            return False
        if checkin is not None and s.get("checkin") != checkin:
            return False
        if checkout is not None and s.get("checkout") != checkout:
            return False
        if a is not None and s.get("adults") != a:
            return False
        if c is not None and s.get("children") != c:
            return False
        if i is not None and s.get("infants") != i:
            return False
        if p is not None and s.get("pets") != p:
            return False
        return True

    matched = [s for s in snapshots if _match(s)]

    # Order by fetched_at desc (fallback to created_at/updated_at/id for stability)
    def _sort_key(s):
        fa = s.get("fetched_at")
        ca = s.get("created_at")
        ua = s.get("updated_at")
        return (
            fa if isinstance(fa, str) else "",
            ua if isinstance(ua, str) else "",
            ca if isinstance(ca, str) else "",
            s.get("id") if isinstance(s.get("id"), str) else "",
        )

    matched.sort(key=_sort_key, reverse=True)

    total = len(matched)
    page = matched[offset:offset + lim]
    next_off = offset + len(page)
    has_more = next_off < total

    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_off}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.b64encode(payload).decode("utf-8")

    resp = {
        "listing": listing_row,
        "snapshots": page,
        "pagination": {
            "total": total,
            "limit": lim,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "offset": offset,
        },
    }
    _log("ok", meta={"listingId": listingId, "returned": len(page), "total": total})
    return resp
